import com.nova.godzillagotchi.*;import java.util.*;import java.io.*;import javax.imageio.*;import java.awt.image.*;
public class ThemeTest {
 static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{Map<String,Object> values=new HashMap<>();values.put("xp",1800);values.put("battle_active",true);values.put("care_name","Gojira");check(Theme.load(CareStoreTest.prefs(values))==Theme.PUPPET,"upgrade preserves current paper look");
 for(int id=0;id<4;id++){Theme.save(CareStoreTest.prefs(values),id);check(Theme.load(CareStoreTest.prefs(values))==id,"theme survives reopen");check(values.get("xp").equals(1800)&&values.get("battle_active").equals(true)&&values.get("care_name").equals("Gojira"),"switch leaves pet and battle unchanged");CareStore.resetEditor(CareStoreTest.prefs(values));check(Theme.load(CareStoreTest.prefs(values))==id,"new egg retains theme");values.put("xp",1800);values.put("battle_active",true);values.put("care_name","Gojira");}
 values.put("theme",99);check(Theme.load(CareStoreTest.prefs(values))==Theme.PUPPET,"invalid saved theme safe fallback");
 for(int id=0;id<4;id++){Set<String> loaded=new HashSet<>(Arrays.asList(Theme.assets(id)));for(String name:loaded)check(new File("res/drawable-nodpi/"+name+".png").isFile(),"available resource "+name);String[] names={"paper_pet","paper_states","paper_attacks","paper_opponents","paper_enemy_attacks","paper_props","paper_scenery"};int[] counts={1,6,4,6,6,12,6};for(int n=0;n<names.length;n++)for(int i=0;i<counts[n];i++){Theme.Sprite sprite=Theme.sprite(id,names[n],i);if(sprite!=null){check(loaded.contains(sprite.name),"theme loads every required image");float[] q=sprite.bounds;check(q[0]>=0&&q[1]>=0&&q[2]>0&&q[3]>0&&q[0]+q[2]<=1.001&&q[1]+q[3]<=1.001,"valid sprite bounds");}}}
 // Resolve every real drawing request, including partial collapse crops, for all player attacks.
 SkinPreview preview=new SkinPreview("res/drawable-nodpi");for(int theme=0;theme<4;theme++)for(int move=0;move<4;move++){SkinRenderer.State s=new SkinRenderer.State();s.theme=theme;s.pet=new Pet(0);s.city=new City();s.rampage=new Rampage(0);s.rampage.hp=1;s.rampage.tick(0);s.rampage.attack(move);for(int time=0;time<=Battle.DURATION_MS[move]+1600;time+=100){s.rampage.tick(time);preview.frame(s,180);}}
 System.out.println("PASS: all theme assets/poses, default migration, saved selection, reset retention, gameplay isolation and four attack/collapse renders per theme");}
}
